    ("lib/models/common.dart", "  Future<String> get path async => appPath.getScriptPath(id.toString());\n\n  Future<FileInfo?> get fileInfo async => File(await path).getFileInfo();\n\n  Future<String?> get content async => readTextFileTask(await path);\n\n  Future<Script> save(String content) async {\n    final file = File(await path);\n    if (!await file.exists()) {\n      await file.create(recursive: true);\n    }\n    await file.writeAsString(content);\n    return copyWith(lastUpdateTime: DateTime.now());\n  }\n\n  Future<Script> update() async {\n    final response = await request.getTextResponseForUrl(url!);\n    return save(response.data ?? '');\n  }\n}\n", "  Future<String> get path async => WebContentRef(WebContentKind.script, id).endpoint(webApiRepository);\n\n  Future<FileInfo?> get fileInfo => WebContentWorkflows(webApiRepository).info(WebContentRef(WebContentKind.script, id));\n\n  Future<String?> get content => WebContentWorkflows(webApiRepository).text(WebContentRef(WebContentKind.script, id));\n\n  Future<Script> save(String content) => WebContentWorkflows(webApiRepository).saveScript(this, content,\n    editVersion: webApiRepository.identities.isBound(ApiIdentity.script, id)\n      ? webApiRepository.captureEditVersion(ApiIdentity.script, this)\n      : webApiRepository.captureCreateVersion(ApiIdentity.script),\n  );\n\n  Future<Script> update() => WebContentWorkflows(webApiRepository).refreshScript(this,\n    editVersion: webApiRepository.captureEditVersion(ApiIdentity.script, this),\n  );\n}\n"),
    ("lib/models/common.dart", "  Future<String> get path => appPath.getProviderCachePath(fileName);\n\n  Future<String> get compiledPath async => '${await path}.mrs';\n\n  Future<String> get corePath => isCompiled ? compiledPath : path;\n\n  Future<FileInfo?> get fileInfo async => File(await path).getFileInfo();", "  Future<String> get path async => WebContentRef(WebContentKind.ruleProvider, id).endpoint(webApiRepository);\n\n  Future<String> get compiledPath => path;\n\n  Future<String> get corePath => path;\n\n  Future<FileInfo?> get fileInfo => WebContentWorkflows(webApiRepository).info(WebContentRef(WebContentKind.ruleProvider, id));"),
    ("lib/common/task.dart", "Future<MigrationData> oldToNowTask(Map<String, Object?> data) async {\n  final homeDir = await appPath.homeDirPath;\n  return compute<\n    ({Map<String, Object?> configMap, String sourcePath, String targetPath}),\n    MigrationData\n  >(_oldToNowTask, (configMap: data, sourcePath: homeDir, targetPath: homeDir));\n}\n\nFuture<MigrationData> _oldToNowTask(\n  ({Map<String, Object?> configMap, String sourcePath, String targetPath}) data,\n) {\n  return migrateLegacyConfig(\n    configMap: data.configMap,\n    sourcePath: data.sourcePath,\n    targetPath: data.targetPath,\n  );\n}\n\nFuture<MigrationData> migrateLegacyConfig({\n  required Map<String, Object?> configMap,\n  required String sourcePath,\n  required String targetPath,\n}) async {\n  final accessControlMap = configMap['accessControl'];\n  final isAccessControl = configMap['isAccessControl'];\n  if (accessControlMap != null) {\n    (accessControlMap as Map)['enable'] = isAccessControl;\n    if (configMap['vpnProps'] != null) {\n      final vpnPropsRaw = configMap['vpnProps'] as Map;\n      vpnPropsRaw['accessControl'] = accessControlMap;\n    }\n  }\n  if (configMap['vpnProps'] != null) {\n    final vpnPropsRaw = configMap['vpnProps'] as Map;\n    vpnPropsRaw['accessControlProps'] = vpnPropsRaw['accessControl'];\n  }\n  configMap['davProps'] = configMap['dav'];\n  final appSettingProps =\n      configMap['appSetting'] as Map<String, dynamic>? ?? {};\n  appSettingProps['restoreStrategy'] = appSettingProps['recoveryStrategy'];\n  configMap['appSettingProps'] = appSettingProps;\n  configMap['proxiesStyleProps'] = configMap['proxiesStyle'];\n  List rawScripts = configMap['scripts'] as List<dynamic>? ?? [];\n  if (rawScripts.isEmpty) {\n    final scriptPropsJson = configMap['scriptProps'] as Map<String, dynamic>?;\n    if (scriptPropsJson != null) {\n      rawScripts = scriptPropsJson['scripts'] as List<dynamic>? ?? [];\n    }\n  }\n  final Map<String, int> idMap = {};\n  final List<Script> scripts = [];\n  for (final rawScript in rawScripts) {\n    final id = rawScript['id'] as String?;\n    final content = rawScript['content'] as String?;\n    final label = rawScript['label'] as String?;\n    if (id == null || content == null || label == null) {\n      continue;\n    }\n    final newId = idMap.updateCacheValue(rawScript['id'], () => snowflake.id);\n    final path = BackupEntries.resolve(targetPath, BackupEntries.script(newId));\n    final file = File(path);\n    await file.safeWriteAsString(content);\n    scripts.add(\n      Script(id: newId, label: label, lastUpdateTime: DateTime.now()),\n    );\n  }\n  final List rawRules = configMap['rules'] as List<dynamic>? ?? [];\n  final List<Rule> rules = [];\n  final List<DisabledRule> disabledRules = [];\n  for (final rawRule in rawRules) {\n    final id = idMap.updateCacheValue(rawRule['id'], () => snowflake.id);\n    rawRule['id'] = id;\n    final value = rawRule['value'] ?? '';\n    rules.add(Rule.parse(value, id: id));\n  }\n  final List rawProfiles = configMap['profiles'] as List<dynamic>? ?? [];\n  final List<Profile> profiles = [];\n  for (final rawProfile in rawProfiles) {\n    final rawId = rawProfile['id'] as String?;\n    if (rawId == null) {\n      continue;\n    }\n    final profileId = idMap.updateCacheValue(rawId, () => snowflake.id);\n    rawProfile['id'] = profileId;\n    final overwrite = rawProfile['overwrite'] as Map?;\n    if (overwrite != null) {\n      final standardOverwrite = overwrite['standardOverwrite'] as Map?;\n      if (standardOverwrite != null) {\n        final addedRules = standardOverwrite['addedRules'] as List? ?? [];\n        for (final addRule in addedRules) {\n          final id = idMap.updateCacheValue(addRule['id'], () => snowflake.id);\n          final value = addRule['value'] ?? '';\n          rules.add(Rule.parse(value, id: id).copyWith(profileId: profileId));\n        }\n        final disabledRuleIds = standardOverwrite['disabledRuleIds'] as List?;\n        if (disabledRuleIds != null) {\n          for (final disabledRuleId in disabledRuleIds) {\n            final newDisabledRuleId = idMap[disabledRuleId];\n            if (newDisabledRuleId != null) {\n              disabledRules.add(\n                DisabledRule(profileId: profileId, ruleId: newDisabledRuleId),\n              );\n            }\n          }\n        }\n      }\n      final scriptOverwrite = overwrite['scriptOverwrite'] as Map?;\n      if (scriptOverwrite != null) {\n        final scriptId = scriptOverwrite['scriptId'] as String?;\n        rawProfile['scriptId'] = scriptId != null ? idMap[scriptId] : null;\n      }\n      rawProfile['extendType'] = overwrite['type'] == ExtendType.script.name\n          ? ExtendType.script.name\n          : ExtendType.standard.name;\n    }\n    final rawUrl = rawProfile['url'];\n    rawProfile['type'] = rawUrl is String && rawUrl.isNotEmpty ? 'url' : 'file';\n\n    final sourceFile = File(\n      BackupEntries.resolve(sourcePath, BackupEntries.profile(rawId)),\n    );\n    final targetFilePath = BackupEntries.resolve(\n      targetPath,\n      BackupEntries.profile(profileId),\n    );\n    await sourceFile.safeCopy(targetFilePath);\n    profiles.add(Profile.fromJson(rawProfile));\n  }\n  final currentProfileId = configMap['currentProfileId'];\n  configMap['currentProfileId'] = currentProfileId != null\n      ? idMap[currentProfileId]\n      : null;\n  return MigrationData(\n    configMap: configMap,\n    profiles: profiles,\n    rules: rules,\n    scripts: scripts,\n    disabledRules: disabledRules,\n  );\n}\n", ""),
    ("lib/providers/actions/scripts.dart", "  void putScript(Script script) {\n    ref.read(scriptsProvider.notifier).put(script);\n    _applyIfInUse(script.id);\n  }\n\n  Future<void> updateScript(Script script) async {\n    final updatingKeys = ref.read(updatingKeysProvider.notifier);\n    final operation = updatingKeys.start(script.updatingKey);\n    try {\n      putScript(await script.update());\n    } finally {\n      updatingKeys.stop(script.updatingKey, operation);\n    }\n  }\n\n", "  Future<Script> putScript(Script script, {ApiEditVersion? editVersion}) async {\n    final repository = database.repository;\n    final version = editVersion ?? (repository.identities.isBound(ApiIdentity.script, script.id)\n        ? repository.captureEditVersion(ApiIdentity.script, script)\n        : repository.captureCreateVersion(ApiIdentity.script));\n    final canonical = await repository.saveCatalog(repository.scripts, script, editVersion: version);\n    _applyIfInUse(canonical.id);\n    return canonical;\n  }\n\n  Future<Script> saveScript(Script draft, String content, {required ApiEditVersion editVersion}) async {\n    final canonical = await WebContentWorkflows(database.repository).saveScript(draft, content, editVersion: editVersion);\n    _applyIfInUse(canonical.id);\n    return canonical;\n  }\n\n  Future<Script> importUrl(String url, {required ApiEditVersion editVersion}) async {\n    final canonical = await WebContentWorkflows(database.repository, confirmSource: showWebSourceConsent).importScriptUrl(url, fallbackLabel: currentAppLocalizations.script, editVersion: editVersion);\n    _applyIfInUse(canonical.id);\n    return canonical;\n  }\n\n  Future<void> deleteScript(Script original, {required ApiEditVersion editVersion}) async {\n    await database.repository.deleteCatalog(database.repository.scripts, [original.id], editVersion: editVersion);\n    _applyIfInUse(original.id);\n  }\n\n  Future<void> updateScript(Script script, {ApiEditVersion? editVersion, bool allowSourceConsent = false}) async {\n    final version = editVersion ?? database.repository.captureEditVersion(ApiIdentity.script, script);\n    final updatingKeys = ref.read(updatingKeysProvider.notifier);\n    final operation = updatingKeys.start(script.updatingKey);\n    try {\n      final canonical = await WebContentWorkflows(database.repository, confirmSource: allowSourceConsent ? showWebSourceConsent : null).saveScript(script, null, refresh: true, editVersion: version);\n      _applyIfInUse(canonical.id);\n    } finally {\n      updatingKeys.stop(script.updatingKey, operation);\n    }\n  }\n\n"),
    ("lib/views/config/scripts.dart", "import 'package:fl_clash/common/common.dart';", "import 'package:fl_clash/common/common.dart';\nimport 'package:fl_clash/database/database.dart';\nimport 'package:fl_clash/web_api/index.dart';\nimport 'package:fl_clash/web_workflows/index.dart';"),
    ("lib/views/config/scripts.dart", "  Future<void> _handleDelete(Script script) async {\n    final appLocalizations = context.appLocalizations;\n    final res = await dialogs.showMessage(\n      title: appLocalizations.tip,\n      message: TextSpan(\n        text: appLocalizations.deleteTip(appLocalizations.script),\n      ),\n      destructive: true,\n      confirmText: appLocalizations.delete,\n    );\n    if (res != true || !mounted) {\n      return;\n    }\n    ref.read(scriptsProvider.notifier).del(script.id);\n    unawaited(_clearEffect(script.id));\n  }\n\n  Future<void> _clearEffect(int id) async {\n    final path = await appPath.getScriptPath(id.toString());\n    await File(path).safeDelete();\n  }\n\n", "  Future<void> _handleDelete(Script script) async {\n    final version = database.repository.captureEditVersion(ApiIdentity.script, script);\n    final appLocalizations = context.appLocalizations;\n    final res = await dialogs.showMessage(\n      title: appLocalizations.tip,\n      message: TextSpan(text: appLocalizations.deleteTip(appLocalizations.script)),\n      destructive: true,\n      confirmText: appLocalizations.delete,\n    );\n    if (res == true && mounted) {\n      await globalState.safeRun(() => _scriptsAction.deleteScript(script, editVersion: version));\n    }\n  }\n\n"),
