    ("lib/views/config/scripts.dart", "  void _handleToEditor([Script? script]) {\n    unawaited(\n      BaseNavigator.push(\n        context,\n        EditorPage(\n          titleEditable: true,\n          title: script?.label ?? '',\n          onSave: (context, title, content) =>\n              _handleEditorSave(context, title, content, script: script),\n          onPop: (context, title, content) {\n            return _handleEditorPop(context, title, content, script: script);\n          },\n          language: Language.javaScript,\n          load: () async => script == null\n              ? CodeForgeDocument.fromText(scriptTemplate)\n              : openEditorFile(await script.path, ifMissing: scriptTemplate),\n        ),\n      ),\n    );\n  }\n\n", "  void _handleToEditor([Script? script]) {\n    final version = script == null\n        ? database.repository.captureCreateVersion(ApiIdentity.script)\n        : database.repository.captureEditVersion(ApiIdentity.script, script);\n    Script? draft = script;\n    Script draftForLabel(String label) {\n      draft = draft?.copyWith(label: label) ?? Script.create(label: label);\n      return draft!;\n    }\n    unawaited(BaseNavigator.push(context, EditorPage(\n      titleEditable: true,\n      title: script?.label ?? '',\n      onSave: (context, title, content) => _handleEditorSave(context, title, content,\n        script: script, editVersion: version, draftForLabel: draftForLabel),\n      onPop: (context, title, content) => _handleEditorPop(context, title, content,\n        script: script, editVersion: version, draftForLabel: draftForLabel),\n      language: Language.javaScript,\n      load: () async => script == null\n          ? CodeForgeDocument.fromText(scriptTemplate)\n          : CodeForgeDocument.fromText(await WebContentWorkflows(database.repository).text(\n              WebContentRef(WebContentKind.script, script.id), editVersion: version)),\n    )));\n  }\n\n"),
