    ("lib/views/config/scripts.dart", "  Future<void> _handleImportFromUrl() async {\n    final appLocalizations = context.appLocalizations;\n    final url = await dialogs.showUrlInput(title: appLocalizations.importUrl);\n    if (url == null) {\n      return;\n    }\n    final res = await globalState.loadingRun(\n      () => request.getTextResponseForUrl(url),\n      title: appLocalizations.importUrl,\n      tag: LoadingTag.scripts,\n    );\n    if (res == null || !mounted) {\n      return;\n    }\n    final fileName =\n        Uri.tryParse(\n          url,\n        )?.pathSegments.lastWhereOrNull((it) => it.isNotEmpty) ??\n        '';\n    await _handleImport(res.data ?? '', url: url, fileName: fileName);\n  }\n\n", "  Future<void> _handleImportFromUrl() async {\n    final version = database.repository.captureCreateVersion(ApiIdentity.script);\n    final appLocalizations = context.appLocalizations;\n    final url = await dialogs.showUrlInput(title: appLocalizations.importUrl);\n    if (url == null) return;\n    await globalState.loadingRun(\n      () => _scriptsAction.importUrl(url, editVersion: version),\n      title: appLocalizations.importUrl, tag: LoadingTag.scripts,\n    );\n  }\n\n"),
