    ("lib/features/mitm/module_editor.dart", "Future<void> offerMitmScripts(WidgetRef ref, MitmModule? module) async {\n  if (module != null && !module.enabled && await acceptMitmScripts()) {\n    ref\n        .read(mitmModulesActionProvider.notifier)\n        .putModule(module.copyWith(enabled: true));\n  }\n}", "Future<void> offerMitmScripts(WidgetRef ref, MitmModule? module) async {\n  if (module == null || module.enabled) return;\n  final version = webApiRepository.captureEditVersion(ApiIdentity.mitmModule, module);\n  if (await acceptMitmScripts()) {\n    await ref.read(mitmModulesActionProvider.notifier).putModule(\n      module.copyWith(enabled: true), editVersion: version,\n    );\n  }\n}"),
