    ("lib/features/mitm/module_editor.dart", "      final saved = module == null\n          ? await action.create(text)\n          : await action.edit(module, text);\n      for (final MapEntry(key: name, value: bytes) in attachments.entries) {\n        await action.attach(saved, name, bytes);\n      }\n      return saved;", "      draft ??= MitmModule(id: snowflake.id, name: appLocalizations.mitmModule, lastUpdateTime: DateTime.now());\n      return module == null\n          ? action.create(text, draft: draft, editVersion: version, attachments: attachments)\n          : action.edit(module, text, editVersion: version, attachments: attachments);"),
