    ("lib/providers/state/profile.dart", "Future<List<MitmModuleSource>> mitmModuleSources(\n  Iterable<MitmModule> modules,\n) async {\n  final directory = await appPath.mitmModulesDirPath;\n  final sources = <MitmModuleSource>[];\n  for (final module in modules) {\n    if (!module.enabled) {\n      continue;\n    }\n    final file = File(join(directory, module.fileName));\n    if (!await file.exists()) {\n      continue;\n    }\n    sources.add(\n      MitmModuleSource(\n        content: await file.readAsString(),\n        arguments: module.arguments,\n        resources: module.resources,\n      ),\n    );\n  }\n  return sources;\n}\n\n", "Future<List<MitmModuleSource>> mitmModuleSources(Iterable<MitmModule> modules) async {\n  final sources = <MitmModuleSource>[];\n  for (final module in modules) {\n    if (!module.enabled) continue;\n    final version = database.repository.captureEditVersion(ApiIdentity.mitmModule, module);\n    final content = await WebContentWorkflows(database.repository).text(\n      WebContentRef(WebContentKind.mitmModule, module.id), editVersion: version,\n    );\n    sources.add(MitmModuleSource(content: content, arguments: module.arguments, resources: module.resources));\n  }\n  return sources;\n}\n\n"),
