    ("lib/views/config/providers.dart", "  void _handleToEditor([ClashProvider? provider]) {\n    unawaited(\n      BaseNavigator.push(\n        context,\n        EditorPage(\n          titleEditable: true,\n          title: provider?.label ?? '',\n          load: () async => provider == null\n              ? CodeForgeDocument.fromText('')\n              : openEditorFile(await provider.path),\n          schema: EditorSchema.provider,\n          onSave: (_, title, content) =>\n              _handleEditorSave(title, content, provider: provider),\n          onPop: (_, title, content) =>\n              _handleEditorPop(title, content, provider: provider),\n        ),\n      ),\n    );\n  }\n\n", "  void _handleToEditor([ClashProvider? provider]) {\n    final version = provider == null\n        ? database.repository.captureCreateVersion(ApiIdentity.clashProvider)\n        : database.repository.captureEditVersion(ApiIdentity.clashProvider, provider);\n    ClashProvider? draft = provider;\n    ClashProvider draftForLabel(String label) {\n      draft = draft?.copyWith(label: label) ?? ClashProvider.create(label: label);\n      return draft!;\n    }\n    unawaited(BaseNavigator.push(context, EditorPage(\n      titleEditable: true,\n      title: provider?.label ?? '',\n      load: () async => provider == null\n          ? CodeForgeDocument.fromText('')\n          : CodeForgeDocument.fromUtf8(await WebContentWorkflows(database.repository).bytes(\n              WebContentRef(WebContentKind.ruleProvider, provider.id), editVersion: version,\n            )),\n      schema: EditorSchema.provider,\n      onSave: (_, title, content) => _handleEditorSave(title, content,\n        provider: provider, editVersion: version, draftForLabel: draftForLabel),\n      onPop: (_, title, content) => _handleEditorPop(title, content,\n        provider: provider, editVersion: version, draftForLabel: draftForLabel),\n    )));\n  }\n\n"),
