    ("lib/providers/actions/icon_sets.dart", "part of '../action.dart';\n\n@Riverpod(keepAlive: true)\nclass IconSetsAction extends _$IconSetsAction {\n  @override\n  void build() {}\n\n  Future<IconSet> importUrl(String url, {String name = ''}) async {\n    final existing = (await database.iconSetsDao.query().get())\n        .where((item) => item.url == url)\n        .firstOrNull;\n    if (existing != null) {\n      return sync(name.isEmpty ? existing : existing.copyWith(name: name));\n    }\n    final content = await _download(url);\n    return _put(\n      IconSet(\n        id: snowflake.id,\n        name: _nameOf(name, content.name, url.urlFileName.fileStem),\n        url: url,\n        icons: content.icons,\n        lastUpdateTime: DateTime.now(),\n      ),\n    );\n  }\n\n  IconSet importContent(String fileName, String content) {\n    final parsed = _parse(content);\n    return _put(\n      IconSet(\n        id: snowflake.id,\n        name: _nameOf('', parsed.name, fileName.fileStem),\n        icons: parsed.icons,\n        lastUpdateTime: DateTime.now(),\n      ),\n    );\n  }\n\n  Future<IconSet> sync(IconSet iconSet) async {\n    final before = await _stored(iconSet.id);\n    final content = await _download(iconSet.url);\n    final latest = before == null ? null : await _stored(iconSet.id);\n    if (before != null && (latest == null || latest.url != before.url)) {\n      return latest ?? iconSet;\n    }\n    final base = switch ((before, latest)) {\n      (final before?, final latest?) => latest.copyWith(\n        name: iconSet.name == before.name ? latest.name : iconSet.name,\n        url: iconSet.url,\n      ),\n      _ => iconSet,\n    };\n    return _put(\n      base.copyWith(icons: content.icons, lastUpdateTime: DateTime.now()),\n    );\n  }\n\n  Future<IconSet?> _stored(int id) async {\n    final rows =\n        ref.read(iconSetsProvider).value ??\n        await database.iconSetsDao.query().get();\n    return rows.where((item) => item.id == id).firstOrNull;\n  }\n\n  IconSet _put(IconSet iconSet) {\n    ref.read(iconSetsProvider.notifier).put(iconSet);\n    return iconSet;\n  }\n\n  String _nameOf(String name, String parsedName, String fallback) {\n    for (final candidate in [name, parsedName, fallback]) {\n      if (candidate.trim().isNotEmpty) {\n        return candidate.trim();\n      }\n    }\n    return currentAppLocalizations.iconSets;\n  }\n\n  Future<({String name, List<IconSetIcon> icons})> _download(String url) async {\n    final response = await request.getTextResponseForUrl(url);\n    return _parse(response.data ?? '');\n  }\n\n  ({String name, List<IconSetIcon> icons}) _parse(String content) {\n    try {\n      return parseIconSet(content);\n    } on FormatException {\n      throw MessageException(currentAppLocalizations.invalidIconSet);\n    }\n  }\n}\n", "part of '../action.dart';\n\n({String name, List<IconSetIcon> icons}) _parseWebIconSet(String content) => parseIconSet(content);\n\n@Riverpod(keepAlive: true)\nclass IconSetsAction extends _$IconSetsAction {\n  @override\n  void build() {}\n\n  Future<IconSet> importUrl(String url, {String name = '', ApiEditVersion? editVersion}) {\n    final version = editVersion ?? database.repository.captureCreateVersion(ApiIdentity.iconSet);\n    return WebIconSetWorkflows(database.repository, confirmSource: showWebSourceConsent).importRemote(url, name: name, editVersion: version);\n  }\n\n  Future<IconSet> importContent(String fileName, String content, {ApiEditVersion? editVersion}) async {\n    final version = editVersion ?? database.repository.captureCreateVersion(ApiIdentity.iconSet);\n    final ({String name, List<IconSetIcon> icons}) parsed;\n    try {\n      parsed = await compute(_parseWebIconSet, content);\n    } on FormatException {\n      throw MessageException(currentAppLocalizations.invalidIconSet);\n    }\n    final name = [parsed.name, fileName.fileStem].firstWhereOrNull((item) => item.trim().isNotEmpty)?.trim() ?? currentAppLocalizations.iconSets;\n    return database.repository.saveCatalog(database.repository.iconSets, IconSet(\n      id: snowflake.id, name: name, icons: parsed.icons, lastUpdateTime: DateTime.now(),\n    ), editVersion: version);\n  }\n\n  Future<IconSet> sync(IconSet iconSet, {ApiEditVersion? editVersion, bool allowSourceConsent = false}) {\n    final version = editVersion ?? database.repository.captureEditVersion(ApiIdentity.iconSet, iconSet);\n    return WebIconSetWorkflows(database.repository, confirmSource: allowSourceConsent ? showWebSourceConsent : null).saveRemote(iconSet, editVersion: version);\n  }\n}\n"),
