    ("lib/views/config/override.dart", "  OverrideState<K, M> read(WidgetRef ref) =>\n      get(_of(ref.read(profileProvider(profileId))));\n\n  @override\n  void update(", "  OverrideState<K, M> read(WidgetRef ref) =>\n      get(_of(ref.read(profileProvider(profileId))));\n\n  @override\n  Future<void> Function(OverrideState<K, M> next) beginEdit(WidgetRef ref) {\n    final original = ref.read(profileProvider(profileId));\n    if (original == null) throw const WebApiException('profile_missing', 'Reload the profile before editing');\n    final version = database.repository.captureEditVersion(ApiIdentity.profile, original);\n    return (next) async {\n      await database.repository.saveProfile(original.copyWith(overrides: set(original.overrides, next)), editVersion: version);\n    };\n  }\n\n  @override\n  void update("),
