    ("lib/views/config/override.dart", "      spec.target.update(ref, (state) {\n        final listed = quickEdit.applyOverrideYaml(state.model, raw).keys;\n        final next = readRelaxed(\n          content,\n          quickEdit.schema,\n          (content) => quickEdit.applyOverrideYaml(state.model, content),\n        );\n        final stillSet = quickEdit\n            .applyOverrideYaml(\n              next.model,\n              quickEdit.overrideYaml(next.model, next.keys),\n            )\n            .keys;\n        return spec.withoutKeys((\n          model: next.model,\n          keys: {...next.keys, ...state.keys.difference(listed)},\n        ), listed.difference(stillSet));\n      });", "      final listed = quickEdit.applyOverrideYaml(original.model, raw).keys;\n      final next = readRelaxed(content, quickEdit.schema,\n        (content) => quickEdit.applyOverrideYaml(original.model, content));\n      final stillSet = quickEdit.applyOverrideYaml(next.model,\n        quickEdit.overrideYaml(next.model, next.keys)).keys;\n      await commit(spec.withoutKeys((\n        model: next.model,\n        keys: {...next.keys, ...original.keys.difference(listed)},\n      ), listed.difference(stillSet)));"),
