    ("lib/state.dart", "    } catch (e, s) {\n      commonPrint.log(\n        title == null", "    } catch (e, s) {\n      if (e is WebApiException) {\n        commonPrint.log('Web API operation failed (${webWorkflowLogCode(e)})', logLevel: LogLevel.warning);\n        try {\n          await showWebWorkflowFailure(e, repository: database.repository);\n        } catch (_) {\n          // A missing UI host must not mask an unresolved command with a UI error.\n          Error.throwWithStackTrace(e, s);\n        }\n        return null;\n      }\n      commonPrint.log(\n        title == null"),
    ("lib/providers/actions/setup.dart", "  /// With a base, [BuiltProfile.yaml] is only the overlay the Core applies.\n  Future<BuiltProfile> getProfile({\n    required SetupState setupState,\n    required PatchClashConfig patchConfig,\n  }) async {\n    final profileId = setupState.profileId;\n    final dialerProxies =\n        setupState.profileType != ProfileType.custom &&\n            setupState.extendType == ExtendType.standard\n        ? setupState.overrides.dialerProxies.validated\n        : const <String, String>{};\n    if (setupState.overrides.dialerProxies.isUnreadable) {\n      setupState.overrides.dialerProxies.validated;\n    }\n    if (profileId == null) {\n      return (yaml: '', md5: '', counts: configCountsOf(const {}), base: null);\n    }\n    final defaultUA = globalState.packageInfo.ua;\n    final networkSetting = ref.read(\n      networkSettingProvider.select(\n        (state) => (\n          appendSystemDns: state.appendSystemDns,\n          bypassPrivateRoute: state.bypassPrivateRoute,\n          authentication: state.authentication,\n        ),\n      ),\n    );\n    final appendSystemDns = networkSetting.appendSystemDns;\n    final isCustom = setupState.profileType == ProfileType.custom;\n    final scriptContent =\n        !isCustom && setupState.extendType == ExtendType.script\n        ? await setupState.script?.content\n        : null;\n    final hasScript = scriptContent?.isNotEmpty == true;\n    final profileBase = !isCustom && !hasScript\n        ? await _core.getProfileBase(profileId)\n        : null;\n    Map<String, dynamic> rawConfig = isCustom\n        ? {\n            'proxies': appProxiesPayload(\n              setupState.appProxies,\n              dialers: setupState.proxyDialers,\n              groups: setupState.proxyGroups,\n            ),\n          }\n        : profileBase?.base.config ?? await _core.readConfig(profileId);\n    final proxyGroups = isCustom ? setupState.proxyGroups : <ProxyGroup>[];\n    final rules = isCustom ? setupState.rules : <Rule>[];\n    if (hasScript) {\n      rawConfig = await handleEvaluate(scriptContent!, rawConfig);\n    }\n    final directory = await appPath.profilesPath;\n    final injected = await _resolveInjectedProviders(\n      setupState,\n      proxyGroups: proxyGroups,\n      rules: rules,\n    );\n    final res = await makeRealProfileTask(\n      MakeRealProfileState(\n        rules: rules,\n        proxyGroups: proxyGroups,\n        injectedProxyProviders: injected.proxies,\n        injectedRuleProviders: injected.rules,\n        profilesPath: directory,\n        profileId: profileId,\n        rawConfig: rawConfig,\n        realPatchConfig: patchConfig,\n        overrides: setupState.overrides,\n        bypassPrivateRoute: networkSetting.bypassPrivateRoute,\n        keepEmptyDnsOverrides: setupState.profileType != ProfileType.custom,\n        appendSystemDns: appendSystemDns,\n        addedRules: setupState.addedRules,\n        defaultUA: defaultUA,\n        authentication: networkSetting.authentication.credentials,\n        matchTarget:\n            profileBase == null ||\n                setupState.matchTarget?.trim().isNotEmpty == true\n            ? setupState.matchTarget\n            : lastMatchTarget(profileBase.base.matchRules),\n        safeMode: ref.read(safeModeProvider),\n        mitmModules: setupState.mitmModules,\n      ),\n    );\n    if (profileBase == null) {\n      return (yaml: res.yaml, md5: res.md5, counts: res.counts, base: null);\n    }\n    final (:base, :path) = profileBase;\n    return (\n      yaml: res.yaml,\n      md5:\n          '${res.md5}${base.digest}${dialerProxies.isEmpty ? '' : jsonEncode(dialerProxies)}'\n              .toMd5(),\n      counts: (\n        groups: res.counts.groups + base.proxyGroups,\n        proxies: res.counts.proxies + base.proxies,\n        rules: res.counts.rules + base.rules,\n      ),\n      base: SetupBase(\n        path: path,\n        overlay: res.yaml,\n        dialerProxies: dialerProxies.isEmpty ? null : dialerProxies,\n      ),\n    );\n  }\n\n", "  /// Builds from one typed setup snapshot; candidate/source handles stay local.\n  Future<BuiltProfile> getProfile({\n    required SetupState setupState,\n    required PatchClashConfig patchConfig,\n  }) => WebSetupWorkflows(database.repository).build(\n    setupState, defaultUA: globalState.packageInfo.ua,\n    safeMode: ref.read(safeModeProvider),\n  );\n\n"),
    ("lib/providers/actions/setup.dart", "  /// Only what the custom profile actually references is injected, so an\n  /// app-level provider costs nothing in the profiles that never name it.\n  Future<({Map<String, dynamic> proxies, Map<String, dynamic> rules})>\n  _resolveInjectedProviders(\n    SetupState setupState, {\n    required List<ProxyGroup> proxyGroups,\n    required List<Rule> rules,\n  }) async {\n    final usedProxyProviders = <String>{\n      for (final proxyGroup in proxyGroups) ...?proxyGroup.use,\n    };\n    final usedRuleProviders = <String>{\n      for (final rule in rules) ...rule.ruleSets,\n      if (setupState.profileType == ProfileType.custom)\n        ...setupState.overrides.ruleSets,\n    };\n    if (usedProxyProviders.isEmpty && usedRuleProviders.isEmpty) {\n      return (\n        proxies: const <String, dynamic>{},\n        rules: const <String, dynamic>{},\n      );\n    }\n    final options = setupState.overrides.proxyProviders;\n    final proxies = <String, dynamic>{};\n    for (final entry in setupState.profileProviders.entries) {\n      if (!usedProxyProviders.contains(entry.key)) {\n        continue;\n      }\n      proxies[entry.key] = {\n        'type': 'file',\n        'path': await appPath.getProfilePath(entry.value.toString()),\n        ...?options[entry.key]?.definition,\n      };\n    }\n    final clashProvidersAction = ref.read(\n      clashProvidersActionProvider.notifier,\n    );\n    final ruleProviders = <String, dynamic>{};\n    for (final provider in setupState.clashProviders) {\n      if (!usedRuleProviders.contains(provider.label)) {\n        continue;\n      }\n      final prepared = await clashProvidersAction.prepare(provider);\n      ruleProviders[prepared.label] = prepared.definition(\n        await prepared.corePath,\n      );\n    }\n    return (proxies: proxies, rules: ruleProviders);\n  }\n\n", ""),
    ("lib/providers/actions/setup.dart", "  Future<String> getProfileWithId(int profileId) async {\n    try {\n      final setupState = await ref.read(setupStateProvider(profileId).future);\n      final patchClashConfig = ref.read(patchClashConfigProvider);\n      final res = await getProfile(\n        setupState: setupState,\n        patchConfig: patchClashConfig,\n      );\n      return switch (res.base) {\n        final base? => await _core.buildProfile(base),\n        null => res.yaml,\n      };\n    } catch (e) {\n      dialogs.showBanner(e.toString(), level: BannerLevel.error);\n    }\n    return '';\n  }\n\n", "  Future<String> getProfileWithId(int profileId) async {\n    BuiltProfile? built;\n    try {\n      final setupState = await ref.read(setupStateProvider(profileId).future);\n      built = await getProfile(setupState: setupState,\n        patchConfig: ref.read(patchClashConfigProvider));\n      return built.yaml;\n    } on WebApiException catch (error) {\n      await showWebWorkflowFailure(error, repository: database.repository);\n    } catch (error) {\n      dialogs.showBanner(compactError(error), level: BannerLevel.error);\n    } finally {\n      WebSetupWorkflows(database.repository).release(built);\n    }\n    return '';\n  }\n\n"),
    ("lib/providers/actions/setup.dart", "  PatchClashConfig _effectivePatchConfig(PatchClashConfig patchConfig) {\n    if (ref.read(safeModeProvider)) {\n      return patchConfig.copyWith(\n        tun: patchConfig.tun.copyWith(enable: false),\n        externalController: ExternalControllerStatus.close,\n      );\n    }\n    final authorized =\n        ref.read(authorizedTunEnableProvider) ==\n        TunAuthorizationState.authorized;\n    return patchConfig.copyWith(\n      tun: patchConfig.tun.copyWith(\n        enable: patchConfig.tun.enable && authorized,\n      ),\n      externalController: patchConfig.secret.isEmpty\n          ? ExternalControllerStatus.close\n          : patchConfig.externalController,\n    );\n  }\n\n", "  PatchClashConfig _effectivePatchConfig(PatchClashConfig patchConfig) =>\n      patchConfig.copyWith(\n        externalController: ExternalControllerStatus.close, secret: '',\n        tun: ref.read(safeModeProvider) ? patchConfig.tun.copyWith(enable: false) : patchConfig.tun,\n      );\n\n"),
    ("lib/providers/actions/setup.dart", "  @visibleForTesting\n  Future<bool> requestAdmin(bool enableTun) async {\n    if (!enableTun || ref.read(safeModeProvider)) {\n      return true;\n    }\n    final authorizationState = ref.read(authorizedTunEnableProvider);\n    if (authorizationState != TunAuthorizationState.none) {\n      return true;\n    }\n\n    final authorizationNotifier = ref.read(\n      authorizedTunEnableProvider.notifier,\n    );\n    authorizationNotifier.value = TunAuthorizationState.unauthorized;\n\n    final code = await authorizeCore();\n\n    switch (code) {\n      case AuthorizeCode.success:\n        authorizationNotifier.value = TunAuthorizationState.authorized;\n        return false;\n      case AuthorizeCode.none:\n        authorizationNotifier.value = TunAuthorizationState.authorized;\n        return true;\n      case AuthorizeCode.error:\n        authorizationNotifier.value = TunAuthorizationState.none;\n        ref\n            .read(patchClashConfigProvider.notifier)\n            .update((state) => state.copyWith.tun(enable: false));\n        dialogs.showBanner(\n          currentAppLocalizations.tunAuthorizationFailed,\n          level: BannerLevel.error,\n        );\n        return true;\n    }\n  }\n\n", "  @visibleForTesting\n  Future<bool> requestAdmin(bool enableTun) async => true;\n\n"),
    ("lib/providers/actions/setup.dart", "  /// Whether the Core runs what the current profile and settings make now.\n  Future<bool> inputsApplied() async {\n    final applied = _appliedInputs;\n    if (applied == null) {\n      return false;\n    }\n    final profileId = ref.read(currentProfileIdProvider);\n    final SetupState setupState;\n    try {\n      setupState = await ref.read(setupStateProvider(profileId).future);\n    } catch (_) {\n      return false;\n    }\n    return applied ==\n        (\n          setupState,\n          _effectivePatchConfig(ref.read(patchClashConfigProvider)),\n          ref.read(networkSettingProvider),\n          _appliedParams,\n        );\n  }\n\n", "  /// Compares the actual one-read setup inputs, not stale ref projections.\n  Future<bool> inputsApplied() async {\n    final applied = _appliedInputs;\n    if (applied == null) return false;\n    try {\n      final state = await ref.read(setupStateProvider(ref.read(currentProfileIdProvider)).future);\n      final webSetup = WebSetupWorkflows(database.repository);\n      return webSetup.sameSource(applied.$1, state) &&\n        applied.$2 == webSetup.patchOf(state, safeMode: ref.read(safeModeProvider)) &&\n        applied.$3 == webSetup.networkOf(state) &&\n        applied.$4 == webSetup.paramsOf(state).copyWith(selectedMap: const {});\n    } on WebApiException {\n      return false;\n    }\n  }\n\n"),
    ("lib/providers/state/profile.dart", "@riverpod\nFuture<SetupState> setupState(Ref ref, int? profileId) async {\n  final profile = ref.watch(profileProvider(profileId));\n  if (profile?.overrides.dialerProxies.isUnreadable == true) {\n    profile!.overrides.dialerProxies.validated;\n  }\n  final scriptId = profile?.scriptId;\n  final profileLastUpdateDate = profile?.lastUpdateDate?.millisecondsSinceEpoch;\n  final profileType = profile?.type ?? ProfileType.file;\n  final extendType = profile?.extendType ?? ExtendType.standard;\n  final overrides = profileType == ProfileType.custom\n      ? ref.watch(\n          patchClashConfigProvider.select(\n            (state) => (profile?.overrides ?? const ProfileOverrides())\n                .overAppTun(state.tunOverride, state.tunOverrideKeys),\n          ),\n        )\n      : ref.watch(\n          patchClashConfigProvider.select(\n            (state) => ProfileOverrides(\n              dns: state.dns,\n              dnsOverrideKeys: state.dnsOverrideKeys.intersection(\n                DnsOverrideKey.normalProfileKeys,\n              ),\n              tun: state.tunOverride,\n              tunOverrideKeys: state.tunOverrideKeys,\n              dialerProxies: extendType == ExtendType.standard\n                  ? profile?.overrides.dialerProxies ??\n                        const DialerProxyOverrides()\n                  : const DialerProxyOverrides(),\n            ),\n          ),\n        );\n  final allProfileProviders = ref.watch(profileProvidersProvider);\n  final mitmModules =\n      mitmFeature &&\n          ref.watch(\n            patchClashConfigProvider.select((state) => state.mitm.enable),\n          )\n      ? ref.watch(mitmModulesProvider.future)\n      : null;\n  List<ProxyGroup> proxyGroups = [];\n  List<Rule> rules = [];\n  List<Rule> addedRules = [];\n  List<ClashProvider> clashProviders = [];\n  Map<String, int> profileProviders = const {};\n  List<CustomProxy> appProxies = [];\n  Map<int, String> proxyDialers = const {};\n  Script? script;\n  if (profileId != null) {\n    if (profileType == ProfileType.custom) {\n      rules = await database.rulesDao.queryProfileRules(profileId).get();\n      proxyGroups = await database.proxyGroupsDao.query(profileId).get();\n      clashProviders = await database.clashProvidersDao.query().get();\n      profileProviders = allProfileProviders;\n      appProxies = await database.customProxiesDao.query().get();\n      proxyDialers = {\n        for (final dialer\n            in await database.proxyDialersDao.query(profileId).get())\n          dialer.proxyId: dialer.target,\n      };\n    } else if (extendType == ExtendType.standard) {\n      addedRules = await database.rulesDao.queryAddedRules(profileId).get();\n    } else if (extendType == ExtendType.script) {\n      script = scriptId == null\n          ? null\n          : await database.scriptsDao.get(scriptId).getSingleOrNull();\n    }\n  }\n  return SetupState(\n    mitmModules: mitmModules == null\n        ? const []\n        : await mitmModuleSources(await mitmModules),\n    clashProviders: clashProviders,\n    profileProviders: profileProviders,\n    appProxies: appProxies,\n    proxyDialers: proxyDialers,\n    rules: rules,\n    proxyGroups: proxyGroups,\n    profileId: profileId,\n    profileLastUpdateDate: profileLastUpdateDate,\n    profileType: profileType,\n    extendType: extendType,\n    addedRules: addedRules,\n    script: script,\n    overrides: overrides,\n    matchTarget:\n        profileType != ProfileType.custom && extendType == ExtendType.standard\n        ? profile?.matchTarget\n        : null,\n  );\n}\n\n", "@riverpod\nFuture<SetupState> setupState(Ref ref, int? profileId) async {\n  final repository = database.repository;\n  final subscription = repository.changes.listen((_) {\n    if (ref.mounted) ref.invalidateSelf();\n  });\n  ref.onDispose(() => unawaited(subscription.cancel()));\n  return WebSetupWorkflows(repository).read(profileId);\n}\n\n"),
    ("lib/common/task.dart", "  final profilesPath = data.profilesPath;\n  final profileId = data.profileId;\n  final overrides = data.overrides;\n  final addedRules = data.addedRules;\n  final appendSystemDns = data.appendSystemDns;\n  final defaultUA = data.defaultUA;\n  String getProvidersFilePathInner(String type, String key) {\n    return join(\n      profilesPath,\n      providersDirectoryName,\n      profileId.toString(),\n      type,\n      key.toMd5(),\n    );\n  }\n\n  void confineProviders(String section, String type) {\n    final providers = rawConfig[section];\n    if (providers is! Map) {\n      return;\n    }\n    for (final name in providers.keys) {\n      final provider = providers[name];\n      if (provider is! Map || provider['type'] == 'inline') {\n        continue;\n      }\n      // Two providers may share a URL and differ only by header.\n      final url = provider['url'];\n      final hasUrl = url is String && url.isNotEmpty;\n      final path = getProvidersFilePathInner(\n        type,\n        hasUrl ? '$name@$url' : '$section/$name',\n      );\n      if (hasUrl) {\n        _migrateLegacyProviderFile(\n          legacyPath: getProvidersFilePathInner(type, url),\n          newPath: path,\n        );\n      }\n      provider['path'] = path;\n    }\n  }\n\n", "  final overrides = data.overrides;\n  final addedRules = data.addedRules;\n  final appendSystemDns = data.appendSystemDns;\n  final defaultUA = data.defaultUA;\n\n  void confineProviders(String section, String type) {\n    final providers = rawConfig[section];\n    if (providers is! Map) return;\n    for (final provider in providers.values) {\n      if (provider is Map) provider.remove('path');\n    }\n  }\n\n"),
    ("lib/common/task.dart", "// Best-effort: a legacy url shared by two providers, or any rename failure,\n// just leaves the file to be re-downloaded under the new path.\nvoid _migrateLegacyProviderFile({\n  required String legacyPath,\n  required String newPath,\n}) {\n  if (legacyPath == newPath || File(newPath).existsSync()) {\n    return;\n  }\n  try {\n    final legacyFile = File(legacyPath);\n    if (legacyFile.existsSync()) {\n      Directory(dirname(newPath)).createSync(recursive: true);\n      legacyFile.renameSync(newPath);\n    }\n  } catch (_) {}\n}\n\n", ""),
