    ("lib/views/backup_and_restore.dart", "  void _submit() {\n    if (_issue(context.appLocalizations) != null) {\n      setState(() {\n        _attempted = true;\n      });\n      return;\n    }\n    ref\n        .read(davSettingProvider.notifier)\n        .update(\n          (_) => DAVProps(\n            uri: _uriController.text,\n            user: _userController.text,\n            password: _passwordController.text,\n            fileName: widget.dav?.fileName ?? defaultDavFileName,\n          ),\n        );\n    Navigator.pop(context);\n  }\n\n  void _delete() {\n    ref.read(davSettingProvider.notifier).update((_) => null);\n    Navigator.pop(context);\n  }\n\n", "  Future<void> _submit() async {\n    if (_saving) return;\n    if (_issue(context.appLocalizations) != null) {\n      setState(() => _attempted = true);\n      return;\n    }\n    setState(() => _saving = true);\n    try {\n      final saved = await globalState.safeRun(() async {\n        await ref.read(davSettingProvider.notifier).setValueAsync(DAVProps(\n          uri: _uriController.text, user: _userController.text,\n          password: _passwordController.text,\n          fileName: widget.dav?.fileName ?? defaultDavFileName,\n        ), editVersion: _editVersion);\n        return true;\n      });\n      if (saved == true && mounted) Navigator.pop(context);\n    } finally {\n      if (mounted) setState(() => _saving = false);\n    }\n  }\n\n  Future<void> _delete() async {\n    if (_saving) return;\n    setState(() => _saving = true);\n    try {\n      final saved = await globalState.safeRun(() async {\n        await ref.read(davSettingProvider.notifier).setValueAsync(null, editVersion: _editVersion);\n        return true;\n      });\n      if (saved == true && mounted) Navigator.pop(context);\n    } finally {\n      if (mounted) setState(() => _saving = false);\n    }\n  }\n\n"),
