    ("lib/views/dashboard/widgets/profile_detail.dart", "  /// Called from build: groups refresh after every applied setup.\n  void watchConfigCounts() {\n    ref.listen(groupsProvider, (_, _) {\n      final cached = _cachedCounts();\n      if (cached == null) {\n        unawaited(_reloadCounts());\n      } else if (cached != configCounts) {\n        _generation++;\n        setState(() {\n          configCounts = cached;\n          configCountsFailed = false;\n        });\n      }\n    });\n  }\n}\n\n", "  /// Runtime counts are observed, never reconstructed from a local file.\n  void watchConfigCounts() {\n    ref.listen(groupsProvider, (_, _) => unawaited(_reloadCounts()));\n  }\n\n  @override\n  void dispose() {\n    _generation++;\n    unawaited(_countsSubscription?.cancel());\n    super.dispose();\n  }\n}\n\n"),
