    ("lib/views/proxies/providers.dart", "  Future<void> _probeFile() async {\n    final clashProvidersAction = ref.read(\n      clashProvidersActionProvider.notifier,\n    );\n    final file = await _probeProviderFile(provider.path);\n    final isAppRuleSet =\n        await clashProvidersAction.remoteProviderOf(provider) != null;\n    if (!mounted || (file == _file && isAppRuleSet == _isAppRuleSet)) {\n      return;\n    }\n    setState(() {\n      _file = file;\n      _isAppRuleSet = isAppRuleSet;\n    });\n  }\n\n", "  Future<void> _probeFile() async {\n    final generation = ++_probeGeneration;\n    try {\n      final binding = await _workflows.resolveRuntimeBinding(provider);\n      final head = await _workflows.head(binding);\n      final document = head.prepared ? await _workflows.read(binding) : null;\n      if (!mounted || generation != _probeGeneration) return;\n      setState(() {\n        _head = document ?? head;\n        _canSync = binding is WebOpaqueProviderSource ||\n          binding is WebManagedProfileProvider && binding.profile.type == ProfileType.url ||\n          binding is WebManagedRuleProvider && binding.provider.isRemote;\n        _file = switch (document?.format) {\n          WebExternalProviderFormat.text => _ProviderFile.text,\n          WebExternalProviderFormat.mrs => _ProviderFile.ruleSet,\n          _ => _ProviderFile.binary,\n        };\n      });\n    } on WebApiException catch (error) {\n      if (!mounted || generation != _probeGeneration) return;\n      setState(() { _head = null; _canSync = false; _file = _ProviderFile.binary; });\n      dialogs.showBanner(webWorkflowFailureMessage(error, context.appLocalizations), level: BannerLevel.error);\n    }\n  }\n\n"),
    ("lib/views/proxies/providers.dart", "  Future<void> _handleSideLoadProvider() async {\n    final proxiesAction = ref.read(proxiesActionProvider.notifier);\n    await globalState.safeRun<void>(() async {\n      final platformFile = await picker.pickerFile();\n      if (platformFile == null) return;\n      await _sideLoadProvider(ref, provider, await platformFile.readBytes());\n    });\n    proxiesAction.updateGroupsDebounce();\n  }\n\n  void _handleEditProvider(BuildContext context) {\n    final path = provider.path;\n    if (path == null || path.isEmpty) return;\n    unawaited(\n      BaseNavigator.push<void>(\n        context,\n        _EditProviderView(provider: provider, path: path),\n      ),\n    );\n  }\n\n  void _handlePreviewProvider(BuildContext context) {\n    final path = provider.path;\n    if (path == null || path.isEmpty) return;\n    final core = ref.read(coreHandlerProvider);\n    final isRuleSet = _file == _ProviderFile.ruleSet;\n    unawaited(\n      BaseNavigator.push<void>(\n        context,\n        EditorPage(\n          title: provider.name,\n          load: isRuleSet\n              ? () async =>\n                    CodeForgeDocument.fromText(await core.dumpRuleSet(path))\n              : () => _openProviderText(path),\n          schema: EditorSchema.provider,\n        ),\n      ),\n    );\n  }\n\n", "  Future<void> _handleSideLoadProvider() async {\n    final head = _head;\n    if (head == null) return;\n    await globalState.safeRun<void>(() async {\n      final file = await picker.pickerFile();\n      if (file == null) return;\n      await _workflows.sideload(head, await file.readBytes());\n      if (mounted) await _confirmProviderApply(context, ref);\n    });\n  }\n\n  Future<void> _handleEditProvider(BuildContext context) async {\n    final head = _head;\n    if (head == null || head is! WebExternalProviderDocument) return;\n    await BaseNavigator.push<void>(context, _EditProviderView(provider: provider, original: head));\n  }\n\n  Future<void> _handlePreviewProvider(BuildContext context) async {\n    final head = _head;\n    if (head == null) return;\n    final preview = await runWebWorkflow(() => _workflows.preview(head.binding), repository: database.repository);\n    if (preview == null || !context.mounted) return;\n    await BaseNavigator.push<void>(context, EditorPage(\n      title: provider.name, load: () async => CodeForgeDocument.fromText(preview.text),\n      schema: EditorSchema.provider,\n    ));\n  }\n\n"),
    ("lib/views/proxies/providers.dart", "Future<CodeForgeDocument> _openProviderText(String path) async {\n  try {\n    return await openEditorFile(path);\n  } on FormatException {\n    throw MessageException(currentAppLocalizations.nonTextProviderFile);\n  }\n}\n\nconst _zstdMagic = [0x28, 0xB5, 0x2F, 0xFD];\nconst _probeLength = 512;\n\nenum _ProviderFile { text, ruleSet, binary }\n\n// An .mrs rule set is a zstd stream and any other binary file gives itself\n// away with a NUL byte; neither can go through the Core's string side-load,\n// but the Core can dump an .mrs set back to text for reading.\nFuture<_ProviderFile> _probeProviderFile(String? path) async {\n  if (path == null || path.isEmpty) {\n    return _ProviderFile.binary;\n  }\n  try {\n    final file = File(path);\n    if (!await file.exists()) {\n      return _ProviderFile.text;\n    }\n    final head = await file\n        .openRead(0, _probeLength)\n        .fold<List<int>>(<int>[], (bytes, chunk) => bytes..addAll(chunk));\n    if (listEquals(head.take(_zstdMagic.length).toList(), _zstdMagic)) {\n      return _ProviderFile.ruleSet;\n    }\n    return head.contains(0) ? _ProviderFile.binary : _ProviderFile.text;\n  } catch (_) {\n    return _ProviderFile.binary;\n  }\n}\n\nString _decodeProviderFile(List<int> bytes) {\n  try {\n    return utf8.decode(bytes);\n  } on FormatException {\n    throw MessageException(currentAppLocalizations.nonTextProviderFile);\n  }\n}\n\nFuture<void> _sideLoadProvider(\n  WidgetRef ref,\n  ExternalProvider provider,\n  List<int> bytes,\n) async {\n  final path = provider.path;\n  if (path == null) return;\n  final data = _decodeProviderFile(bytes);\n  await ref\n      .read(proxiesActionProvider.notifier)\n      .sideLoadExternalProvider(provider, data, showLoading: true);\n  await File(path).safeWriteAsBytes(bytes);\n}\n\nclass _EditProviderView extends ConsumerStatefulWidget {\n  final ExternalProvider provider;\n  final String path;\n\n  const _EditProviderView({required this.provider, required this.path});\n\n  @override\n  ConsumerState<_EditProviderView> createState() => _EditProviderViewState();\n}\n\nclass _EditProviderViewState extends ConsumerState<_EditProviderView> {\n  Future<void> _handleSave(BuildContext context, EditorContent content) async {\n    final proxiesAction = ref.read(proxiesActionProvider.notifier);\n    final saved = await globalState.safeRun<bool>(() async {\n      await _sideLoadProvider(ref, widget.provider, await content.readBytes());\n      return true;\n    }, silence: false);\n    if (saved != true) {\n      return;\n    }\n    proxiesAction.updateGroupsDebounce();\n    if (context.mounted) {\n      Navigator.of(context).pop();\n    }\n  }\n\n  Future<bool> _handlePop(BuildContext context, EditorContent content) async {\n    final res = await dialogs.showSaveChanges(title: widget.provider.name);\n    if (res == null) {\n      return false;\n    }\n    if (!res || !context.mounted) {\n      return true;\n    }\n    unawaited(_handleSave(context, content));\n    return false;\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return EditorPage(\n      title: widget.provider.name,\n      load: () => _openProviderText(widget.path),\n      schema: EditorSchema.provider,\n      onSave: (context, _, content) => _handleSave(context, content),\n      onPop: (context, _, content) => _handlePop(context, content),\n    );\n  }\n}\n", "enum _ProviderFile { text, ruleSet, binary }\n\nFuture<bool> _confirmProviderApply(BuildContext context, WidgetRef ref) async {\n  final l = context.appLocalizations;\n  final confirmed = await dialogs.showMessage(context: context,\n    message: TextSpan(text: l.webProviderSavedApplyTip), confirmText: l.applyNow);\n  if (confirmed != true || !context.mounted) return false;\n  final applied = await ref.read(setupActionProvider.notifier).applyProfile(force: true);\n  if (applied && context.mounted) {\n    await ref.read(providersProvider.notifier).syncProviders();\n    await ref.read(proxiesActionProvider.notifier).updateGroups();\n  }\n  return applied;\n}\n\nclass _EditProviderView extends ConsumerStatefulWidget {\n  final ExternalProvider provider;\n  final WebExternalProviderDocument original;\n  const _EditProviderView({required this.provider, required this.original});\n  @override\n  ConsumerState<_EditProviderView> createState() => _EditProviderViewState();\n}\n\nclass _EditProviderViewState extends ConsumerState<_EditProviderView> {\n  String? _savedBase64;\n  bool _saving = false;\n\n  Future<void> _handleSave(BuildContext context, EditorContent content) async {\n    if (_saving) return;\n    setState(() => _saving = true);\n    try {\n      final bytes = await content.readBytes();\n      final encoded = base64Encode(bytes);\n      final saved = await runWebWorkflow<bool>(() async {\n        if (_savedBase64 == null) {\n          await webExternalProviderWorkflows(database.repository).write(widget.original, bytes);\n          _savedBase64 = encoded;\n        } else if (_savedBase64 != encoded) {\n          throw const WebApiException('edit_snapshot_mismatch', 'This edit was already saved; reload its current revision before another write');\n        }\n        return true;\n      }, repository: database.repository);\n      if (saved != true || !context.mounted) return;\n      if (await _confirmProviderApply(context, ref) && context.mounted) Navigator.of(context).pop();\n      // Cancellation keeps the editor and the already committed draft visible.\n    } finally {\n      if (mounted) setState(() => _saving = false);\n    }\n  }\n\n  Future<bool> _handlePop(BuildContext context, EditorContent content) async {\n    if (_saving) return false;\n    final res = await dialogs.showSaveChanges(title: widget.provider.name);\n    if (res == null) return false;\n    if (!res || !context.mounted) return true;\n    unawaited(_handleSave(context, content));\n    return false;\n  }\n\n  @override\n  Widget build(BuildContext context) => PopGuard(onPop: (_) => !_saving,\n    child: EditorPage(title: widget.provider.name,\n      load: () async => CodeForgeDocument.fromUtf8(widget.original.bytes),\n      schema: EditorSchema.provider,\n      onSave: (context, _, content) => _handleSave(context, content),\n      onPop: (context, _, content) => _handlePop(context, content)));\n}\n"),
